(7502893, 1194987, 163081, '<td valign="top">Very natural scene, Looks like an early cold morning. Not over processed. A 9 from me and my Red Dragon Award<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1173262" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg"/></a></td>', 'Very natural scene, Looks like an early cold morning. Not over processed. A 9 from me and my Red Dragon Award', '2017-03-01 09:06:56.000000', NULL, 1),
(7502904, 1196124, 185795, '<td valign="top">A tighter crop would be good!</td>', 'A tighter crop would be good!', '2017-03-01 10:35:45.000000', NULL, 1),
(7502905, 1196183, 124815, '<td valign="top">Very interesting composition. The saturation and sharpness makes the image truly digital but interesting anyway</td>', 'Very interesting composition. The saturation and sharpness makes the image truly digital but interesting anyway', '2017-03-01 10:37:16.000000', NULL, 1),
(7502909, 1196142, 124815, '<td valign="top">The central pack of riders and their almost synchronized movement makes this a very engaging picture. Great colors also. Makes me think of Raoul Dufy</td>', 'The central pack of riders and their almost synchronized movement makes this a very engaging picture. Great colors also. Makes me think of Raoul Dufy', '2017-03-01 10:42:04.000000', NULL, 1),
