INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7504323, 1196192, 68504, '<td valign="top">excellent showing of light!</td>', 'excellent showing of light!', '2017-03-08 00:11:51.000000', NULL, 0),
(7504324, 1195954, 79955, '<td valign="top">Super Congrats Siew Hoon !!</td>', 'Super Congrats Siew Hoon !!', '2017-03-08 00:14:40.000000', NULL, 0),
